"""Build the portable stakeholder presentation from original project evidence."""
from pathlib import Path
import base64
import html

HERE = Path(__file__).resolve().parent
EVIDENCE = HERE.parent / "ui-ux-review" / "evidence"

def shot(path, alt, caption, kind=""):
    data = base64.b64encode((EVIDENCE / path).read_bytes()).decode()
    return f'''<figure class="{kind}"><button class="image-button" aria-label="Enlarge: {html.escape(alt, quote=True)}"><img src="data:image/png;base64,{data}" alt="{html.escape(alt, quote=True)}" data-source="{path}"></button><figcaption>{caption}</figcaption></figure>'''

def section(number, title, body, lead="", extra=""):
    tag = "h1" if number == 1 else "h2"
    return f'''<section id="page-{number}" class="page {extra}" aria-labelledby="title-{number}"><div class="page-head"><p class="eyebrow">{number:02} / Tack · UI &amp; UX update</p><{tag} id="title-{number}" tabindex="-1">{title}</{tag}>{f'<p class="lead">{lead}</p>' if lead else ''}</div>{body}</section>'''

pages = []
pages.append(section(1, "A clearer board.<br>More dependable work.", f'''
<div class="split hero"><div><p class="status">Implemented &amp; verified locally</p><p>Tack keeps team tracking simple: capture a title, move the card, keep working.</p><p>The upgrade brings daily actions into reach and gives interrupted work a clear recovery path.</p><p class="next">Next: prepare the two-week team pilot.</p><p class="note">20 September 2026<br>All three UI/UX milestones complete. Deployment and pilot observations are still ahead.</p></div>
{shot('u3/production-board-1440.png','Current desktop board showing four columns and capture above the cards','Current local production build · original six-card board.')}</div>''', extra="cover"))

pages.append(section(2, "Make room for the work.", f'''
<div class="comparison">
{shot('board-1440.png','Desktop before: large introductory heading and capture below each card list','Before · 1440 × 900 · development build.')}
{shot('u2/board-1440.png','Desktop after U2: compact heading and capture above each card list','After U2 · 1440 × 900 · production build.')}
</div><div class="result-row"><p><strong>353 → 248 px</strong><span>Column start, measured from the top.</span></p><p><strong>606 → 333 px</strong><span>Capture start in the In progress column.</span></p><p>Compact heading. Larger card text. Capture before the list. Secondary actions under Options.</p></div><p class="note">Same six cards, same viewport. Rounded CSS pixels. These are layout measurements, not measured time savings. The baseline’s development indicator is not app UI.</p>''', 'A smaller header and earlier capture keep the board at the center of the experience.'))

pages.append(section(3, "Capture is visible on a phone.", f'''
<div class="phone-comparison"><div class="phone-pair">
{shot('board-390.png','Phone before: capture sits below the 900 pixel viewport','Before · 390 × 900.')}
{shot('u2/board-390.png','Phone after U2: New card, status selection, capture and the first card are visible','After U2 · 390 × 900.')}
</div><div><div class="big-number">912 → 391<span>px from the top to capture</span></div><p>A labeled <b>New card</b> action stays in the header. Filters collapse, while active choices stay visible.</p><p>Smaller screens show one chosen status at a time. Desktop shows all four columns from 1180 px.</p><p class="note">Same original data, selected In progress column. A separate 390 × 844 check also showed capture and the first card together. Chromium mobile emulation.</p></div></div>'''))

pages.append(section(4, "Know what saved. Keep what didn’t.", f'''
<div class="split portrait"><div><p class="lead">A failed edit stays in the editor with a clear choice: <b>Retry save</b> or <b>Discard changes</b>.</p><ul><li>Close and Archive wait for the latest text.</li><li>Copying a link has its own confirmation.</li><li>Recovered issue drafts are reviewed before saving.</li><li>Keyboard focus stays within the dialog and returns to the task.</li></ul><p class="note">Draft recovery is scoped to the same tab and account, for up to 24 hours. It does not provide offline sync or cross-user conflict resolution.</p></div>
{shot('u1/save-recovery-mobile.png','Failed save with retained text, Link copied, Not saved, Retry save and Discard changes','U1 controlled failure fixture. Captured before U2 rearranged the editor.','phone')}</div>'''))

pages.append(section(5, "Keep the user’s chosen view.", f'''
<div class="split portrait"><div><p class="lead">An empty column can be the right place to work.</p><p>The selected Ready column stays selected even when the current search matches a card elsewhere.</p><ul><li>Search and filters stay visible and removable.</li><li>Creating a card retains the current filters.</li><li>A hidden new card gets a persistent <b>Show card</b> / <b>Clear filters</b> notice.</li><li>Shared card links retain their context through sign-in.</li></ul><p class="note">Shown: U2 filtered-empty view on the original six-card board. This screenshot demonstrates retained selection; the hidden-new-card notice is a separate tested state.</p></div>
{shot('u2/filtered-empty-390.png','Ready remains selected with no matching cards, a visible TCK-1 search chip and Clear filters','Ready stays selected · 390 × 844.','phone')}</div>'''))

pages.append(section(6, "A failure now has a next step.", f'''
<div class="split wide-image"><div><p>Shared updates and saved changes have separate status.</p><p><b>Retry refresh</b> addresses an out-of-date board. <b>Retry action</b> or <b>Check board</b> addresses a move that could not be confirmed.</p><p>Failed capture keeps the title and avoids automatic resubmission. Expired sessions offer sign-in in another tab.</p><p class="note">A lost response can leave a write’s outcome uncertain. Retained input and checking the board support a deliberate retry.</p></div>
{shot('u3/board-recovery-desktop.png','Board with separate persistent refresh failure and failed move notices','U3 controlled failure fixture · sample cards. Confirmed saves cannot clear a refresh warning.')}</div>''', 'Keep the input, explain the uncertainty, and offer recovery beside the task.'))

pages.append(section(7, "Make account changes understandable.", f'''
<div class="split wide-image"><div><p>Pending, failure, and success messages stay beside the affected account.</p><ul><li>Password changes offer Cancel.</li><li>Protected-account reasons are visible without hover.</li><li>New-account feedback stays at the creation form.</li><li>Label removal explains its effect on every card before confirmation.</li></ul><p class="note">Existing permissions remain in place. Passwords are not copied to browser storage.</p></div>
{shot('u3/team-feedback-desktop.png','Password update failure beside Maya Chen sample account with retained masked input and Cancel','U3 synthetic account fixture · scrolled to the affected row. Example names and addresses are test data.')}</div>'''))

pages.append(section(8, "Verified locally. Ready for pilot preparation.", '''
<div class="verification"><div class="metric"><strong>51</strong><span>browser checks passed</span><small>5 intentional skips</small></div><div class="metric"><strong>20</strong><span>domain / export / return-path checks passed</span></div><div class="metric"><strong>7</strong><span>viewport widths checked</span><small>320–1440 px, plus 200% text</small></div></div>
<div class="two-col"><div><h3>Additional confidence</h3><p>Lint, TypeScript, and production build passed. Automated accessibility scans passed in the tested board, editor, labels, and Team states.</p><p>Final production inspection found no page errors or horizontal overflow in the checked views. The original six cards were unchanged.</p></div><div><h3>What the pilot must establish</h3><p>Whether people can capture, find, and move cards without help—and whether they trust saved and shared state.</p><p>Real-device, Firefox/WebKit, screen-reader, and representative-user coverage remain unverified. This is not an accessibility-conformance claim.</p></div></div>
<p class="note">After feedback cleanup: 31 focused checks passed, 1 duplicate skipped; final label-focus checks: 4 passed. These overlap earlier runs and are not additive. Recorded application results from U3-DELIVERY.md; the suite was not rerun for this presentation.</p>'''))

pages.append(section(9, "The next decision is the pilot.", '''
<p class="lead">Keep the product boundary simple: Backlog → Ready → In progress → Done.</p>
<div class="pilot-steps"><div><span>01</span><h3>Name the people</h3><p>Choose a pilot owner, operations contact, participants, dates, and feedback-log location.</p></div><div><span>02</span><h3>Prepare the service</h3><p>Choose the TLS host and off-host backups. Deploy, verify health, complete a restore drill, and inspect an export.</p></div><div><span>03</span><h3>Observe for two weeks</h3><p>Introduce the workflow in ten minutes. Check on days 2, 7, and 14. Record friction and repeated workarounds.</p></div><div><span>04</span><h3>Choose from evidence</h3><p>Address operational defects immediately. At the review, select at most one next product improvement.</p></div></div>
<p class="closing">The UI/UX upgrade is complete locally.<br>The next evidence should come from the team using it.</p>
<p class="note">Source records in the project: docs/ui-ux-review/PLAN.md, U1-DELIVERY.md, U2-DELIVERY.md, U3-DELIVERY.md; evidence/u2/comparison.json; evidence/u3/production-check.json; ROADMAP.md; PILOT.md. Review, QA, and discussion remain in existing tools. No deployment was performed during this upgrade.</p>'''))

