script = '''
const pages=[...document.querySelectorAll('.page')],counter=document.querySelector('#counter'),mode=document.querySelector('#mode'),prev=document.querySelector('#prev'),next=document.querySelector('#next');
let index=0,present=false,lastImage=null;
function update(){pages.forEach((p,i)=>p.classList.toggle('active',i===index));counter.textContent=`${index+1} / ${pages.length}`;prev.disabled=index===0;next.disabled=index===pages.length-1;mode.textContent=present?'Read all':'Present';mode.setAttribute('aria-pressed',String(present));}
function go(n,focus=false){index=Math.max(0,Math.min(pages.length-1,n));update();if(present){window.scrollTo(0,0);if(focus)pages[index].querySelector('h1,h2').focus({preventScroll:true});}else pages[index].scrollIntoView({behavior:'instant'});history.replaceState(null,'','#page-'+(index+1));}
mode.addEventListener('click',()=>{present=!present;document.body.classList.toggle('present',present);go(index,true)});prev.addEventListener('click',()=>go(index-1,true));next.addEventListener('click',()=>go(index+1,true));
const observer=new IntersectionObserver(entries=>{if(present)return;const candidates=entries.filter(e=>e.isIntersecting);if(candidates.length){index=pages.indexOf(candidates[0].target);update();}},{rootMargin:'-70px 0px -60% 0px'});pages.forEach(p=>observer.observe(p));
const zoom=document.querySelector('#zoom'),zoomImage=document.querySelector('.zoom-image'),zoomTitle=document.querySelector('#zoom-title'),size=document.querySelector('#zoom-size');
document.querySelectorAll('.image-button').forEach(button=>button.addEventListener('click',()=>{const img=button.querySelector('img');lastImage=button;zoomImage.src=img.src;zoomImage.alt=img.alt;zoomTitle.textContent=img.alt;zoom.classList.add('fit');size.textContent='Actual size';zoom.showModal();}));
document.querySelector('.zoom-close').addEventListener('click',()=>zoom.close());zoom.addEventListener('close',()=>{zoomImage.removeAttribute('src');lastImage?.focus();});zoom.addEventListener('click',e=>{if(e.target===zoom){const r=zoom.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)zoom.close();}});size.addEventListener('click',()=>{const fit=zoom.classList.toggle('fit');size.textContent=fit?'Actual size':'Fit image';});
document.addEventListener('keydown',e=>{if(zoom.open||e.altKey||e.ctrlKey||e.metaKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(present&&['ArrowRight','PageDown','ArrowLeft','PageUp','Home','End'].includes(e.key)){e.preventDefault();go(e.key==='Home'?0:e.key==='End'?pages.length-1:index+(['ArrowRight','PageDown'].includes(e.key)?1:-1),true);}if(e.key==='Escape'&&present){present=false;document.body.classList.remove('present');go(index,true);}});
const initial=Number(location.hash.replace('#page-',''))-1;if(Number.isInteger(initial)&&initial>=0&&initial<pages.length)index=initial;update();
'''

document = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tack — UI &amp; UX stakeholder overview</title><meta name="description" content="A stakeholder briefing on Tack’s delivered UI and UX improvements, original screenshots, verification and pilot next steps."><style>{css}</style></head><body><a class="skip" href="#main">Skip to presentation</a><header class="toolbar"><div class="brand"><i>•</i>Tack <span class="key-hint">Stakeholder overview · September 2026</span></div><nav class="controls" aria-label="Presentation controls"><button id="prev" aria-label="Previous section">←</button><span id="counter" aria-live="polite">1 / 9</span><button id="next" aria-label="Next section">→</button><button id="mode" class="primary" aria-pressed="false">Present</button></nav></header><main id="main">{''.join(pages)}</main><dialog id="zoom" aria-labelledby="zoom-title"><div class="zoom-bar"><p id="zoom-title"></p><div class="controls"><button id="zoom-size">Actual size</button><button class="zoom-close">Close</button></div></div><img class="zoom-image" alt=""><p class="zoom-help">Original screenshot · Escape closes this view.</p></dialog><script>{script}</script></body></html>'''
